const eq=(name,actual,expected)=>{if(actual!==expected) issues.push({name,actual,expected});};
const replaceOnce=(text,from,to,name)=>{const count=text.split(from).length-1;eq(name+' count',count,1);return text.replace(from,to);};
const board=fs.readFileSync('docs/BOARD.md','utf8');
const verification=fs.readFileSync('docs/VERIFICATION.md','utf8');
let reverseBoard=board;
for(const change of r.tracking.boardChanges)reverseBoard=replaceOnce(reverseBoard,change.next,change.old,'board change');
eq('board limited to selected replacements',sha(reverseBoard),b.agp.files['docs/BOARD.md'].sha256);
let reverseVerification=replaceOnce(verification,r.tracking.section,'','new verification section');
reverseVerification=replaceOnce(reverseVerification,r.tracking.mx24.next,r.tracking.mx24.old,'current MX24 row');
eq('verification history preserved',sha(reverseVerification),b.agp.files['docs/VERIFICATION.md'].sha256);
const allowed=new Set(['docs/BOARD.md','docs/VERIFICATION.md']);
let preserved=0;
for(const [file,id] of Object.entries(b.agp.files)){
 if(allowed.has(file))continue;
 const bytes=fs.readFileSync(file);
 eq(file+' bytes',bytes.length,id.bytes);eq(file+' hash',sha(bytes),id.sha256);preserved++;
}
const dirty=g(root,'status','--porcelain=v1','--untracked-files=all').trimEnd().split('\n').filter(Boolean).map(x=>x.slice(3)).sort();
eq('dirty set',JSON.stringify(dirty),JSON.stringify([...b.agp.dirty,receiptPath].sort()));
for(const [name,args] of Object.entries({head:['rev-parse','HEAD'],origin:['rev-parse','origin/main'],candidate:['rev-parse','repair/disposition-write-observation'],candidateParent:['rev-parse','repair/disposition-write-observation^']})){
 eq('agp '+name,g(root,...args).trim(),b.agp[name]);
}
eq('agp index',g(root,'diff','--cached','--name-status'),b.agp.index);
const zorg='/home/apnex/taceng/zorg';
eq('zorg head',g(zorg,'rev-parse','HEAD').trim(),b.zorg.head);
eq('zorg origin',g(zorg,'rev-parse','origin/main').trim(),b.zorg.origin);
eq('zorg index',g(zorg,'diff','--cached','--name-status'),b.zorg.index);
eq('zorg status',g(zorg,'status','--porcelain=v1','--untracked-files=all'),b.zorg.status);
for(const source of b.sources){
 const bytes=fs.readFileSync(source.path);
 eq(source.path+' bytes',bytes.length,source.bytes);eq(source.path+' hash',sha(bytes),source.sha256);
 const raw=r.retainedInputs.files.find(x=>x.path===source.path);
 if(!raw){issues.push({name:'missing raw input',path:source.path});continue;}
 eq(source.path+' retained raw',sha(raw.raw),source.sha256);
}
const frozen=Object.keys(b.agp.files).filter(x=>x.startsWith('docs/reviews/browser-peer-scale-assurance/'));
for(const file of frozen)eq('frozen HEAD '+file,sha(fs.readFileSync(file)),sha(execFileSync('git',['show','HEAD:'+file],{cwd:root})));
eq('build exit',r.build.exit_code,0);
eq('installation exit',r.installation.exit_code,0);
let regressionCount=0;
for(const run of r.regressionRuns){
 eq(run.name+' exit',run.exit_code,0);
 const total=Number(run.output.match(/(?:# |ℹ )tests (\d+)/)?.[1]);
 const pass=Number(run.output.match(/(?:# |ℹ )pass (\d+)/)?.[1]);
 const fail=Number(run.output.match(/(?:# |ℹ )fail (\d+)/)?.[1]);
 eq(run.name+' total',total,run.expected);eq(run.name+' pass',pass,run.expected);eq(run.name+' fail',fail,0);
 regressionCount+=total;
}
eq('regression count',regressionCount,18);
const links=[];
const slug=(x)=>x.toLowerCase().replace(/<[^>]*>/g,'').replace(/[^\p{L}\p{N}\s_-]/gu,'').trim().replace(/\s/g,'-');
for(const [from,body] of [['docs/BOARD.md',r.tracking.boardChanges.map(c=>c.next).join('\n')],['docs/VERIFICATION.md',r.tracking.mx24.next+'\n'+r.tracking.section]]){
 for(const match of body.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const [target,anchor]=match[1].split('#');const file=target?path.resolve(path.dirname(path.resolve(from)),target):path.resolve(from);
  if(!fs.existsSync(file)){issues.push({name:'missing link target',from,target});continue;}
  if(anchor){const heads=[...fs.readFileSync(file,'utf8').matchAll(/^#{1,6} +(.+)$/gm)].map(h=>slug(h[1]));if(!heads.includes(anchor))issues.push({name:'missing anchor',from,target,anchor});}
  links.push({from,target:match[1]});
 }
}
const candidate=r.temporaryCheckout.worktree;
if(fs.existsSync(candidate)){
 eq('candidate checked out HEAD',g(candidate,'rev-parse','HEAD').trim(),b.agp.candidate);
 eq('candidate clean',g(candidate,'status','--porcelain=v1','--untracked-files=all'),'');
 eq('candidate common dir',fs.realpathSync(path.resolve(candidate,g(candidate,'rev-parse','--git-common-dir').trim())),fs.realpathSync(path.resolve(root,g(root,'rev-parse','--git-common-dir').trim())));
}else{
 eq('worktree registrations restored',g(root,'worktree','list','--porcelain'),b.agp.worktrees);
}
eq('old missing checkout still absent',fs.existsSync(b.staleCandidateWorktree.path),false);
const artifactHashes=Object.fromEntries(['docs/BOARD.md','docs/VERIFICATION.md'].map(file=>[file,{bytes:fs.statSync(file).size,sha256:sha(fs.readFileSync(file))}]));
console.log(JSON.stringify({measuredAt:new Date().toISOString(),pass:issues.length===0,preservedFiles:preserved,dirtyCount:dirty.length,frozenPacketFiles:frozen.length,rawInputs:b.sources.length,regressionCount,links,artifactHashes,temporaryCheckoutExists:fs.existsSync(candidate),issues},null,2));
